Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  try { await Firebase.initializeApp(); } catch (_) {}
  final store = await Store.load();
  await store.firebaseConnect();
  runApp(DainPay(store));
}
String uid() => '${DateTime.now().microsecondsSinceEpoch}_${Random().nextInt(99999)}';
String money(double n) => '${n.toStringAsFixed(2)} د.ل';
String day(DateTime d) => '${d.day.toString().padLeft(2,'0')}/${d.month.toString().padLeft(2,'0')}/${d.year}';

class Customer {
  String id,name,phone; double limit;
  Customer(this.id,this.name,this.phone,[this.limit=0]);
  Map<String,dynamic> json()=>{'id':id,'name':name,'phone':phone,'limit':limit};
  factory Customer.from(Map<String,dynamic> j)=>Customer('${j['id']??''}','${j['name']??''}','${j['phone']??''}',(j['limit'] as num?)?.toDouble()??0);
}
class Tx {
  String id,customerId,type,note,receipt; double amount; DateTime date;
  Tx(this.id,this.customerId,this.type,this.amount,this.date,this.note,[this.receipt='']);
  Map<String,dynamic> json()=>{'id':id,'customerId':customerId,'type':type,'amount':amount,'date':date.toIso8601String(),'note':note,'receipt':receipt};
  factory Tx.from(Map<String,dynamic> j)=>Tx('${j['id']??''}','${j['customerId']??''}','${j['type']??'debt'}',(j['amount'] as num?)?.toDouble()??0,DateTime.tryParse('${j['date']}')??DateTime.now(),'${j['note']??''}','${j['receipt']??''}');
}
class Store extends ChangeNotifier {
  late SharedPreferences p; List<Customer> customers=[]; List<Tx> tx=[]; String shop='DainPay — دَيْن';
  String msg='السلام عليكم [الاسم]، تذكير لطيف بخصوص المتبقي عليكم قدره [المبلغ] د.ل.'; bool dark=false; String cloudUid=''; bool firebase=false, syncing=false;
  static Future<Store> load() async { final s=Store(); s.p=await SharedPreferences.getInstance(); s.shop=s.p.getString('shop')??s.shop; s.msg=s.p.getString('msg')??s.msg; s.dark=s.p.getBool('dark')??false;
    try{s.customers=(jsonDecode(s.p.getString('customers')??'[]') as List).map((e)=>Customer.from(Map<String,dynamic>.from(e))).toList();}catch(_){ }
    try{s.tx=(jsonDecode(s.p.getString('tx')??'[]') as List).map((e)=>Tx.from(Map<String,dynamic>.from(e))).toList();}catch(_){ } return s; }
  Future<void> firebaseConnect() async { try{ User? u=FirebaseAuth.instance.currentUser; u??=(await FirebaseAuth.instance.signInAnonymously()).user; if(u==null)return; cloudUid=u.uid; firebase=true; await pull(); }catch(_){firebase=false;} notifyListeners(); }
  CollectionReference<Map<String,dynamic>> get cr=>FirebaseFirestore.instance.collection('users').doc(cloudUid).collection('customers');
  CollectionReference<Map<String,dynamic>> get tr=>FirebaseFirestore.instance.collection('users').doc(cloudUid).collection('transactions');
  Future<void> pull() async { if(!firebase||cloudUid.isEmpty||syncing)return; syncing=true; try{ final a=await cr.get(), b=await tr.get(); for(final d in a.docs){final c=Customer.from(d.data()); final i=customers.indexWhere((x)=>x.id==c.id); if(i<0)customers.add(c);else customers[i]=c;} for(final d in b.docs){final x=d.data(); final raw=x['date']; final dt=raw is Timestamp?raw.toDate():DateTime.tryParse('$raw')??DateTime.now(); final t=Tx('${x['id']??d.id}','${x['customerId']??''}','${x['type']??'debt'}',(x['amount'] as num?)?.toDouble()??0,dt,'${x['note']??''}','${x['receipt']??''}'); final i=tx.indexWhere((z)=>z.id==t.id); if(i<0)tx.add(t);else tx[i]=t;} await local(); }catch(_){ } syncing=false; }
  Future<void> cloudSave() async { if(!firebase||cloudUid.isEmpty||syncing)return; syncing=true; try{final b=FirebaseFirestore.instance.batch(); for(final c in customers)b.set(cr.doc(c.id),c.json()); for(final t in tx)b.set(tr.doc(t.id),{...t.json(),'date':Timestamp.fromDate(t.date)}); await b.commit();}catch(_){ }syncing=false; }
  Future<void> local() async {await p.setString('customers',jsonEncode(customers.map((e)=>e.json()).toList()));await p.setString('tx',jsonEncode(tx.map((e)=>e.json()).toList()));await p.setString('shop',shop);await p.setString('msg',msg);await p.setBool('dark',dark);}
  Future<void> save() async {await local();notifyListeners();await cloudSave();}
  double balance(String id)=>tx.where((x)=>x.customerId==id).fold(0.0,(v,x)=>v+(x.type=='debt'?x.amount:-x.amount));
  double debts(String id)=>tx.where((x)=>x.customerId==id&&x.type=='debt').fold(0.0,(v,x)=>v+x.amount);
  double paid(String id)=>tx.where((x)=>x.customerId==id&&x.type=='payment').fold(0.0,(v,x)=>v+x.amount);
  String risk(String id){final b=balance(id);if(b<=0)return'مسدد';final a=tx.where((x)=>x.customerId==id&&x.type=='debt').toList()..sort((a,b)=>b.date.compareTo(a.date));if(a.isEmpty)return'حديث';final d=DateTime.now().difference(a.first.date).inDays;return d>90?'خطر':d>30?'متأخر':'حديث';}
}
