class _HomeState extends State<Home>{String q='',filter='all';@override Widget build(BuildContext c){final s=widget.s;final list=s.customers.where((x){final b=s.balance(x.id);return(q.isEmpty||x.name.contains(q)||x.phone.contains(q))&&(filter=='all'||filter=='debt'&&b>0||filter=='paid'&&b<=0);}).toList()..sort((a,b)=>s.balance(b.id).compareTo(s.balance(a.id)));final total=s.customers.fold<double>(0,(v,x)=>v+max(0,s.balance(x.id)));return Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(s.shop,style:const TextStyle(fontWeight:FontWeight.bold)),actions:[IconButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Settings(s))),icon:const Icon(Icons.settings))]),body:ListView(padding:const EdgeInsets.all(12),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(children:[Expanded(child:Stat('المتبقي',money(total))),Expanded(child:Stat('العملاء','${s.customers.length}'))]))),TextField(decoration:const InputDecoration(hintText:'بحث بالاسم أو الهاتف',prefixIcon:Icon(Icons.search)),onChanged:(v)=>setState(()=>q=v)),const SizedBox(height:8),Wrap(spacing:8,children:[ChoiceChip(label:const Text('الكل'),selected:filter=='all',onSelected:(_)=>setState(()=>filter='all')),ChoiceChip(label:const Text('عليهم دين'),selected:filter=='debt',onSelected:(_)=>setState(()=>filter='debt')),ChoiceChip(label:const Text('مسدد'),selected:filter=='paid',onSelected:(_)=>setState(()=>filter='paid'))]),...list.map((x)=>Card(child:ListTile(onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>CustomerPage(s,x))),leading:CircleAvatar(child:Text(x.name.isEmpty?'؟':x.name[0])),title:Text(x.name),subtitle:Text('${x.phone}\n${s.risk(x.id)} • دين ${money(s.debts(x.id))} • مسدد ${money(s.paid(x.id))}'),isThreeLine:true,trailing:Text(money(s.balance(x.id)),style:const TextStyle(fontWeight:FontWeight.bold)))))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>AddCustomer(s))),icon:const Icon(Icons.person_add),label:const Text('عميل'))));}}
