class _AddTxState extends State<AddTx>{final amount=TextEditingController(),note=TextEditingController();final picker=ImagePicker();String type='debt',receipt='';Future<void>pick()async{final src=await showModalBottomSheet<ImageSource>(context:context,builder:(_)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[ListTile(title:const Text('الكاميرا'),leading:const Icon(Icons.camera_alt),onTap:()=>Navigator.pop(context,ImageSource.camera)),ListTile(title:const Text('المعرض'),leading:const Icon(Icons.photo),onTap:()=>Navigator.pop(context,ImageSource.gallery))])));if(src==null)return;final image=await picker.pickImage(source:src,imageQuality:75,maxWidth:1600,maxHeight:2200);if(image==null)return;final d=await getApplicationDocumentsDirectory();final dir=Directory('${d.path}/receipts');await dir.create(recursive:true);final f=await File(image.path).copy('${dir.path}/${uid()}.jpg');if(mounted)setState(()=>receipt=f.path);}Future<void>save()async{final v=double.tryParse(amount.text.replaceAll(',','.'));if(v==null||v<=0)return;widget.s.tx.add(Tx(uid(),widget.x.id,type,v,DateTime.now(),note.text.trim(),receipt));await widget.s.save();if(mounted)Navigator.pop(context);}@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text('عملية — ${widget.x.name}')),body:ListView(padding:const EdgeInsets.all(16),children:[SegmentedButton<String>(segments:const[ButtonSegment(value:'debt',label:Text('دَين')),ButtonSegment(value:'payment',label:Text('تسديد'))],selected:{type},onSelectionChanged:(v)=>setState(()=>type=v.first)),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'المبلغ بالدينار الليبي')),TextField(controller:note,maxLines:3,decoration:const InputDecoration(labelText:'ملاحظات')),Card(child:ListTile(title:const Text('صورة الإيصال'),subtitle:Text(receipt.isEmpty?'اختيارية':'تم الإرفاق'),trailing:IconButton(onPressed:pick,icon:const Icon(Icons.add_a_photo)))),if(receipt.isNotEmpty)Image.file(File(receipt),height:180,fit:BoxFit.cover),const SizedBox(height:16),FilledButton(onPressed:save,child:const Text('حفظ العملية'))]))));}
